// Préparation d'une annonce BOAMP : champs API + eForms + texte_llm + type_annonce
const r = $json;
const arr = v => v == null ? [] : Array.isArray(v) ? v : [v];
const txt = v => {
  if (v == null) return '';
  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return v.map(txt).filter(Boolean).join(' ');
  if (typeof v === 'object') return txt(v['#text'] ?? v['$'] ?? v._ ?? v.value ?? '');
  return '';
};
const num = v => { const n = parseFloat(txt(v).replace(/\s/g, '').replace(',', '.')); return Number.isFinite(n) ? n : null; };
const date = v => { const s = txt(v); return s ? s.slice(0, 10) : null; };
const find = (o, key) => { // premier objet trouvé pour une clé, en profondeur
  if (!o || typeof o !== 'object') return undefined;
  if (key in o) return o[key];
  for (const k of Object.keys(o)) { const f = find(o[k], key); if (f !== undefined) return f; }
  return undefined;
};

// donnees arrive en chaîne JSON
let d = r.donnees;
if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
const ef = d?.EFORMS ?? {};
const cn = ef.ContractNotice ?? Object.values(ef)[0] ?? {};

const projet = cn['cac:ProcurementProject'] ?? {};
const lots = arr(cn['cac:ProcurementProjectLot']);
const lotProj = l => l?.['cac:ProcurementProject'] ?? {};

// CPV
const cpv = [...new Set([projet, ...lots.map(lotProj)]
  .flatMap(p => arr(p['cac:MainCommodityClassification']))
  .map(c => txt(c['cbc:ItemClassificationCode'])).filter(Boolean))];

// PME, période, lieu
const adapte_pme = lots.some(l => txt(lotProj(l)['cbc:SMESuitableIndicator']) === 'true')
  || (lots.length ? false : null);
const periode = lotProj(lots[0])['cac:PlannedPeriod'] ?? {};
const date_debut = date(periode['cbc:StartDate']);
const date_fin = date(periode['cbc:EndDate']);
const adresse = arr(lotProj(lots[0])['cac:RealizedLocation'])[0]?.['cac:Address'] ?? {};
const code_postal = txt(adresse['cbc:PostalZone']) || null;
const nuts = txt(adresse['cbc:CountrySubentityCode']) || null;

// Date limite : champ API, sinon date de remise du premier lot
const dl = lots[0]?.['cac:TenderingProcess']?.['cac:TenderSubmissionDeadlinePeriod'];
const date_limite = r.datelimitereponse
  ?? (dl?.['cbc:EndDate'] ? date(dl['cbc:EndDate']) + 'T' + (txt(dl['cbc:EndTime']) || '12:00:00+01:00') : null);

// Budgets : écart de plus de 5 % entre projet et lots = incohérence signalée
const montant = p => num(p?.['cac:RequestedTenderTotal']?.['cbc:EstimatedOverallContractAmount']);
const budget_projet = montant(projet);
const montantsLots = lots.map(l => montant(lotProj(l))).filter(n => n != null);
const budget_lots = montantsLots.length ? montantsLots.reduce((a, b) => a + b, 0) : null;
const budget_incoherent = budget_projet != null && budget_lots != null
  && Math.abs(budget_projet - budget_lots) / Math.max(budget_projet, budget_lots, 1) > 0.05;

// Motif du rectificatif
const changes = find(cn, 'efac:Changes');
const motif_changement = txt(arr(changes?.['efac:ChangeReason'])[0]?.['efbc:ReasonDescription']) || null;

// Texte pour le LLM (4 000 caractères max), nettoyé des mentions répétitives
const nettoie = s => s.split(/(?<=[.;])\s+/)
  .filter(p => !/signature [ée]lectronique|R\.?\s?2132-7/i.test(p)).join(' ').trim();
const parts = [];
parts.push('Objet : ' + (r.objet ?? ''));
const descProjet = nettoie(txt(projet['cbc:Description']));
if (descProjet) parts.push('Description : ' + descProjet);
const prestations = nettoie(txt(cn['cac:TenderingProcess']?.['cbc:Description']));
if (prestations) parts.push('Prestations : ' + prestations);
lots.forEach((l, i) => {
  const p = lotProj(l);
  const nom = txt(p['cbc:Name']);
  const note = nettoie(txt(p['cbc:Note']));
  const options = nettoie(txt(arr(l['cac:ContractExtension'] ?? p['cac:ContractExtension'])
    .map(c => c['cbc:OptionsDescription'])));
  parts.push(['Lot ' + (i + 1) + (nom ? ' : ' + nom : ''), note && 'Note : ' + note, options && 'Options : ' + options]
    .filter(Boolean).join(' | '));
});
const noteProjet = nettoie(txt(projet['cbc:Note']));
if (noteProjet) parts.push('Note du projet : ' + noteProjet);
parts.push('Indices : descripteurs = ' + arr(r.descripteur_libelle).join(', ')
  + ' ; type de marché = ' + arr(r.type_marche).join(', '));
const texte_llm = parts.join('\n').slice(0, 4000);

const nature = r.nature ?? '';
const etat = r.etat ?? '';
const type_annonce =
    nature === 'APPEL_OFFRE' && etat === 'INITIAL'      ? 'initial'
  : nature === 'APPEL_OFFRE' && etat === 'RECTIFICATIF' ? 'rectificatif'
  : nature === 'ATTRIBUTION'                            ? 'attribution'
  : 'autre';

return {
  json: {
    idweb: r.idweb,
    contractfolderid: r.contractfolderid ?? '',
    annonce_lie: arr(r.annonce_lie),
    nature, etat, type_annonce,
    objet: r.objet ?? null,
    acheteur: r.nomacheteur ?? null,
    date_parution: r.dateparution ?? null,
    date_limite,
    departements: arr(r.code_departement),
    type_marche: arr(r.type_marche),
    url_avis: r.url_avis ?? null,
    cpv, nb_lots: lots.length || null, adapte_pme, date_debut, date_fin, code_postal, nuts,
    budget_projet, budget_lots, budget_incoherent,
    motif_changement,
    texte_llm,
    donnees_brutes: r,
  },
};

