const out = $json.output;
const ok = !!out && typeof out === 'object' && typeof out.resume === 'string' && out.resume.trim() !== '';
return {
  json: {
    idweb: $('Entrée LLM A').item.json.idweb,
    parse_ok: ok,
    ...(ok ? out : {}),
    erreur: ok ? null : (typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error ?? 'sortie invalide')),
    prompt_version: 'wf1-v1',
    model: 'gpt-4o-mini',
  },
};

// Ligne à créer dans appels_offres (annonce préparée + sortie du LLM)
const a = $('Hash texte').item.json;
const l = $json;
return {
  json: {
    contractfolderid: a.contractfolderid || null,
    idwebs: [a.idweb],
    id_derniere_annonce: a.idweb,
    url_derniere_annonce: a.url_avis,
    statut: a.type_annonce === 'initial' ? 'ouvert' : 'rectifie',
    objet: a.objet, acheteur: a.acheteur, date_parution: a.date_parution, date_limite: a.date_limite,
    departements: a.departements, code_postal: a.code_postal, nuts: a.nuts,
    type_marche: a.type_marche, cpv: a.cpv, nb_lots: a.nb_lots, adapte_pme: a.adapte_pme,
    date_debut: a.date_debut, date_fin: a.date_fin,
    budget_projet: a.budget_projet, budget_lots: a.budget_lots, budget_incoherent: a.budget_incoherent,
    hash_texte: a.hash_texte,
    resume: l.resume, secteur: l.secteur, budget_texte: l.budget_texte ?? null, duree: l.duree ?? null,
    exigences_particulieres: l.exigences_particulieres ?? null, lots_resume: l.lots_resume ?? null,
    prompt_version: l.prompt_version, model: l.model,
  },
};

// Après "Créer appels_offres" : $json est la ligne créée (avec son id).
// On n'indexe que des informations stables ; date limite, statut et budget sont lus à jour par l'agent.
const m = $json;
const liste = (v) => (Array.isArray(v) ? v.join(', ') : v);
const lignes = [
  `Objet : ${m.objet ?? ''}`,
  m.resume && `Résumé : ${m.resume}`,
  m.secteur && `Secteur : ${m.secteur}`,
  m.acheteur && `Acheteur : ${m.acheteur}`,
  m.departements?.length && `Départements : ${liste(m.departements)}`,
  m.lots_resume && `Lots : ${m.lots_resume}`,
  m.exigences_particulieres && `Exigences : ${liste(m.exigences_particulieres)}`,
  m.duree && `Durée : ${m.duree}`,
].filter(Boolean);
return {
  json: {
    content: lignes.join('\n'),
    metadata: { id_marche: m.id, idwebs: (m.idwebs ?? []).join(','), secteur: m.secteur ?? null },
  },
};

