// WF2 — nœud Code "Vérifier le profil" — Run Once for Each Item
// Contrôle et normalise un profil avant la sélection. Aucun LLM : règles fixes.
const SECTEURS = [
  'BTP et travaux', 'informatique et numérique', 'audiovisuel et équipements',
  'conseil et études', 'formation', 'nettoyage et services', 'espaces verts',
  'transport et logistique', 'santé', 'restauration',
  'communication et événementiel', 'autre',
];
const p = $json;
const erreurs = [];
const liste = (v) => (Array.isArray(v) ? v : v == null || v === '' ? [] : String(v).split(','))
  .map((x) => String(x).trim()).filter(Boolean);

// Identité
const id = String(p.id ?? '').trim();
if (!id) erreurs.push('id manquant');
const email = String(p.email ?? '').trim().toLowerCase();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) erreurs.push(`e-mail invalide : « ${p.email ?? ''} »`);

// Secteurs : uniquement les 12 valeurs de la liste (comparaison sans tenir compte des majuscules)
const parNom = Object.fromEntries(SECTEURS.map((s) => [s.toLowerCase(), s]));
const secteursBruts = liste(p.secteurs);
const secteurs = [...new Set(secteursBruts.map((s) => parNom[s.toLowerCase()]).filter(Boolean))];
const inconnus = secteursBruts.filter((s) => !parNom[s.toLowerCase()]);
if (!secteursBruts.length) erreurs.push('aucun secteur');
if (inconnus.length) erreurs.push(`secteur(s) hors liste : ${inconnus.join(', ')}`);

// Départements : "1" -> "01", Corse 2A/2B, outre-mer 971 à 976
const departements = [...new Set(liste(p.departements).map((d) => d.toUpperCase().padStart(2, '0')))];
const depInvalides = departements.filter((d) => !/^(0[1-9]|1\d|[3-8]\d|9[0-5]|2[1-9]|2A|2B|97[1-6])$/.test(d));
if (depInvalides.length) erreurs.push(`département(s) invalide(s) : ${depInvalides.join(', ')}`);

// Budget minimum
const budget_min = p.budget_min == null || p.budget_min === '' ? 0 : Number(String(p.budget_min).replace(/\s/g, ''));
if (!Number.isFinite(budget_min) || budget_min < 0) erreurs.push(`budget minimum invalide : « ${p.budget_min} »`);

return { json: {
  ...p,
  id, email, secteurs, departements,
  budget_min: Number.isFinite(budget_min) ? budget_min : 0,
  pme_seulement: p.pme_seulement === true || p.pme_seulement === 'true',
  profil_valide: erreurs.length === 0,
  erreurs: erreurs.join(' ; '),
} };

// Texte envoyé au LLM : le profil + les marchés sélectionnés (informations utiles seulement)
const p = $('Un profil à la fois').item.json;
const marches = $json.marches || [];
const lignes = marches.map((m) => [
  `[id ${m.id}] ${m.objet}`,
  m.resume && `Résumé : ${m.resume}`,
  `Secteur : ${m.secteur}`,
  m.lots_resume && `Lots : ${m.lots_resume}`,
  m.exigences_particulieres && `Exigences : ${m.exigences_particulieres}`,
].filter(Boolean).join('\n'));
const texte =
  `PROFIL\nNom : ${p.nom}\nActivité : ${p.activite}\nDépartements : ${(p.departements || []).join(', ')}\n\n` +
  `MARCHÉS\n${lignes.join('\n\n')}`;
return { json: { texte_llm: texte, nb: marches.length } };

// E-mail du digest : marchés sélectionnés + phrase du LLM (si disponible)
const p = $('Un profil à la fois').item.json;
const marches = $('Sélection').item.json.marches || [];
const raisons = Array.isArray($json.output?.raisons) ? $json.output.raisons : [];
const pourquoi = Object.fromEntries(raisons.map((r) => [String(r.id), r.pourquoi]));

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const eur = (n) => Number(n).toLocaleString('fr-FR') + ' € HT';
const quand = (d) => new Date(d).toLocaleString('fr-FR', {
  timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const jours = (d) => Math.ceil((new Date(d) - Date.now()) / 86400000);

const blocs = marches.map((m) => {
  const maj = m.version_envoyee != null;
  const budget = m.budget_incoherent ? 'à vérifier (montants contradictoires dans l’annonce)'
    : m.budget != null ? eur(m.budget) : 'non précisé';
  const raison = pourquoi[String(m.id)];
  return `
  <div style="margin:0 0 18px;padding:0 0 16px;border-bottom:1px solid #e3e3e3">
    ${maj ? '<div style="color:#B3261E;font-weight:bold;margin-bottom:4px">Mis à jour</div>' : ''}
    <div style="font-size:16px;font-weight:bold">${esc(m.objet)}</div>
    <div style="color:#555">${esc(m.acheteur)} · ${esc((m.departements || []).join(', '))}</div>
    ${m.resume ? `<p style="margin:8px 0">${esc(m.resume)}</p>` : ''}
    ${raison ? `<p style="margin:8px 0;padding:6px 10px;background:#f2f6fc"><b>Pourquoi pour vous :</b> ${esc(raison)}</p>` : ''}
    <div><b>Date limite :</b> ${quand(m.date_limite)} (dans ${jours(m.date_limite)} jours)</div>
    <div><b>Budget :</b> ${budget}${m.adapte_pme ? ' · adapté aux PME' : ''}</div>
    ${m.duree ? `<div><b>Durée :</b> ${esc(m.duree)}</div>` : ''}
    ${m.exigences_particulieres ? `<div><b>À savoir :</b> ${esc(m.exigences_particulieres)}</div>` : ''}
    ${maj && m.dernier_motif ? `<div><b>Motif de la mise à jour :</b> ${esc(m.dernier_motif)}</div>` : ''}
    <div style="margin-top:6px"><a href="${m.url_derniere_annonce}">Voir l’annonce</a></div>
  </div>`;
}).join('');

const n = marches.length;
return { json: {
  profil_id: p.id,
  email: p.email,
  sujet: `Radar Marchés Publics : ${n} opportunité${n > 1 ? 's' : ''} pour ${p.nom}`,
  html: `<div style="font-family:Arial,sans-serif;max-width:640px">
    <p>Bonjour ${esc(p.nom)},</p>
    <p>Voici ${n} marché${n > 1 ? 's' : ''} public${n > 1 ? 's' : ''} qui correspond${n > 1 ? 'ent' : ''} à votre profil.</p>
    ${blocs}
    <p style="color:#888;font-size:12px">Radar Marchés Publics · sélection automatique, à vérifier sur l’annonce officielle.</p>
  </div>`,
  marches_envoyes: marches.map((m) => ({ id: m.id, version: m.version })),
} };

