// Réunit la ligne de référence et la sortie du LLM (même logique que Normaliser A/B du WF1)
const ref = $('Annonces étiquetées').item.json;
const cfg = $('Config2').first().json;
const out = $json.output;
const ok = !!out && typeof out === 'object' && typeof out.resume === 'string' && out.resume.trim() !== '';
return { json: {
  ref,
  run: cfg.run, prompt_version: cfg.prompt_version, model: cfg.model,
  idweb: ref.idweb,
  parse_ok: ok,
  parse_erreur: ok ? null : (typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error ?? 'sortie invalide')),
  ...(ok ? out : {}),
} };

// Graders déterministes : format compliance, output correctness, faithfulness (proxy par mots-clés)
const SECTEURS = ['BTP et travaux', 'informatique et numérique', 'audiovisuel et équipements',
  'conseil et études', 'formation', 'nettoyage et services', 'espaces verts', 'transport et logistique',
  'santé', 'restauration', 'communication et événementiel', 'autre'];
const o = $json;
const ref = o.ref;
const vide = (v) => v === null || v === undefined || String(v).trim() === '';
const norm = (s) => String(s ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const MOTS_VIDES = new Set(['de','des','du','la','le','les','un','une','et','en','a','au','aux','pour','sur','par','avec','dans','d','l','si']);
const motsCles = (s) => norm(s).split(' ').filter((m) => m.length > 2 && !MOTS_VIDES.has(m));
const recouvrement = (a, b) => { // part des mots-clés de a présents dans b
  const ma = motsCles(a); if (!ma.length) return 1;
  const tb = new Set(motsCles(b)); return ma.filter((m) => tb.has(m)).length / ma.length;
};
const elements = (s) => (vide(s) ? [] : String(s).split(';').map((x) => x.trim()).filter(Boolean));
const nombres = (s) => (String(s ?? '').match(/\d+/g) || []);

// 1. Format compliance
const format_ok = o.parse_ok && SECTEURS.includes(o.secteur)
  && (o.budget_texte == null || typeof o.budget_texte === 'number') ? 1 : 0;
const resume_mots = vide(o.resume) ? 0 : String(o.resume).trim().split(/\s+/).length;
const resume_longueur_ok = resume_mots > 0 && resume_mots <= 25 ? 1 : 0;

// 2. Output correctness
const secteur_ok = format_ok && o.secteur === ref.secteur_ref ? 1 : 0;
// VP bonne valeur · FP valeur fausse ou inventée · FN valeur manquée · VN absente des deux côtés
const statut = (r, l, egal) => vide(r) && vide(l) ? 'VN' : vide(r) ? 'FP' : vide(l) ? 'FN' : egal(r, l) ? 'VP' : 'FP';
const budget_statut = o.parse_ok
  ? statut(ref.budget_ref, o.budget_texte, (r, l) => Math.abs(Number(l) - Number(r)) / Number(r) <= 0.05) : 'FN';
// Durée : tous les nombres de la référence doivent apparaître dans la réponse
const duree_statut = o.parse_ok
  ? statut(ref.duree_ref, o.duree, (r, l) => nombres(r).length > 0 ? nombres(r).every((n) => nombres(l).includes(n)) : recouvrement(r, l) >= 0.5)
  : 'FN';
const exRef = elements(ref.exigences_ref), exLlm = elements(o.exigences_particulieres);
const exigences_rappel = exRef.length === 0 ? (exLlm.length === 0 ? 1 : null)
  : exRef.filter((e) => exLlm.some((l) => recouvrement(e, l) >= 0.5)).length / exRef.length;

// 3. Faithfulness : chaque exigence du LLM doit être ancrée dans le texte source
const exigences_ancrage = exLlm.length === 0 ? 1
  : exLlm.filter((l) => recouvrement(l, ref.texte_llm) >= 0.6).length / exLlm.length;
const invente = (vide(ref.budget_ref) && !vide(o.budget_texte)) || (vide(ref.duree_ref) && !vide(o.duree));
const faithfulness = o.parse_ok && !invente && exigences_ancrage >= 0.8 ? 1 : 0;

return { json: { ...o, format_ok, resume_mots, resume_longueur_ok, secteur_ok,
  budget_statut, duree_statut, exigences_rappel, exigences_ancrage, faithfulness } };

// Texte envoyé au LLM-juge : la source et ce que l'extraction en a tiré
const o = $json;
return { json: { ...o, texte_juge:
  `TEXTE SOURCE :\n${o.ref.texte_llm}\n\n` +
  `RÉSUMÉ PRODUIT : ${o.resume ?? '(aucun)'}\n` +
  `EXIGENCES PRODUITES : ${o.exigences_particulieres ?? '(aucune)'}` } };

// Ajoute le verdict du juge (null si le juge a échoué ou si l'extraction n'a rien produit)
const o = $('Texte pour le juge').item.json;
const j = $json.output;
const ok = o.parse_ok && j && typeof j === 'object';
const { ref, texte_juge, ...res } = o;
return { json: { ...res,
  juge_resume_fidele: ok ? (j.resume_fidele ? 1 : 0) : null,
  juge_resume_clarte: ok && Number.isInteger(j.clarte) ? Math.min(5, Math.max(1, j.clarte)) : null,
  juge_exigences_fideles: ok ? (j.exigences_fideles ? 1 : 0) : null,
  juge_justification: ok ? j.justification ?? null : null,
} };

// Un seul item après l'enregistrement de toutes les annonces : déclenche le rapport
const n = $input.all().length;
return [{ json: { run: $('Config2').first().json.run, annonces_evaluees: n } }];

// Verdict go / no-go : chaque métrique est comparée à son seuil d'acceptation
const r = $input.first().json;
const m = r.metriques || {};
const s = r.stabilite || {};
const SEUILS = [
  // dimension, libellé, valeur, seuil, sens
  ['Format compliance', 'JSON valide et conforme au schéma (%)', m.format_pct, 98, '>='],
  ['Format compliance', 'Résumé de 25 mots maximum (%)', m.resume_longueur_pct, 95, '>='],
  ['Output correctness', 'Secteur correct (%)', m.secteur_pct, 85, '>='],
  ['Output correctness', 'Budget : précision (%)', m.budget_precision_pct, 95, '>='],
  ['Output correctness', 'Budget : rappel (%)', m.budget_rappel_pct, 70, '>='],
  ['Output correctness', 'Durée : précision (%)', m.duree_precision_pct, 85, '>='],
  ['Output correctness', 'Exigences : rappel (%)', m.exigences_rappel_pct, 70, '>='],
  ['Faithfulness', 'Aucune information inventée (%)', m.faithfulness_pct, 95, '>='],
  ['Faithfulness', 'Exigences ancrées dans le texte (%)', m.exigences_ancrage_pct, 90, '>='],
  ['Faithfulness', 'Résumé fidèle selon le juge (%)', m.juge_resume_fidele_pct, 90, '>='],
  ['Faithfulness', 'Exigences fidèles selon le juge (%)', m.juge_exigences_fideles_pct, 90, '>='],
  ['Qualité', 'Clarté du résumé selon le juge (sur 5)', m.juge_clarte_moyenne, 4, '>='],
  ['Stabilité', 'Même secteur à chaque run (%)', s.stabilite_secteur_pct, 90, '>='],
];
const lignes = SEUILS.map(([dimension, metrique, valeur, seuil]) => ({
  dimension, metrique, valeur: valeur ?? 'non mesuré', seuil,
  resultat: valeur == null ? 'à mesurer' : Number(valeur) >= seuil ? 'OK' : 'KO',
}));
const ko = lignes.filter((l) => l.resultat === 'KO');
const manquants = lignes.filter((l) => l.resultat === 'à mesurer');
const verdict = ko.length ? 'NO-GO' : manquants.length ? 'INCOMPLET' : 'GO';
return [{ json: {
  verdict,
  run: r.run,
  prompt_version: r.prompt_version,
  annonces: m.n,
  raison: ko.length ? `${ko.length} seuil(s) non atteint(s) : ${ko.map((l) => l.metrique).join(' ; ')}`
    : manquants.length ? `À mesurer : ${manquants.map((l) => l.metrique).join(' ; ')}` : 'Tous les seuils sont atteints.',
  avertissement: (m.n ?? 0) < 30 ? `Seulement ${m.n} annonces : une erreur pèse ${Math.round(100 / Math.max(m.n, 1))} points. Visez 30 à 50 annonces avant la mise en production.` : null,
  tableau: lignes,
  erreurs_a_examiner: r.erreurs,
} }];
